            "// A course: how many lessons, how many done.\nconst course = { title: \"JavaScript: Zero to Builder\", total: 7, completed: 0 };\nconst learnerName = \"Amina\";\n\nfunction percent(done, whole) {\n  if (whole === 0) return 0;              // the empty case, defined up front\n  return Math.round((done / whole) * 100);\n}\n\nfunction completeOne(state) {\n  if (state.completed >= state.total) return state.completed;  // never exceed 100\n  state.completed += 1;                   // mutating the OBJECT the binding points at\n  return state.completed;\n}\n\ncompleteOne(course);        // 1\ncompleteOne(course);        // 2\nconsole.log(`${learnerName}: ${percent(course.completed, course.total)}%`);\n// → \"Amina: 29%\"    (2/7 = 0.2857… → round → 29)\n\nconsole.log(percent(0, 0));   // 0 — the guard clause, not NaN\nconsole.log(percent(7, 7));   // 100\n\nlet attempts = 0;\nattempts = attempts + 1;      // let: the binding changes\nconsole.log(typeof attempts); // \"number\"\nconsole.log(course.total + 1); // 8 — arithmetic, no string involved\nconsole.log(\"7\" + 1);          // \"71\" — string concatenation: the + trap\nconsole.log(\"7\" - 1);          // 6  — numeric conversion: the - asymmetry",
